+    // These external controls are ignored so an accidental broad run
+    // cannot include the deliberately failing negative observation.
+    struct ControlWorker {
+        release: Option<mpsc::Sender<()>>,
+        worker: Option<thread::JoinHandle<()>>,
+    }
+
+    impl Drop for ControlWorker {
+        fn drop(&mut self) {
+            // Closing this sender releases the worker even on an assertion
+            // failure; always join before allowing that panic out.
+            drop(self.release.take());
+            if let Some(worker) = self.worker.take() {
+                let joined = worker.join();
+                if !thread::panicking() {
+                    assert!(joined.is_ok(), "control worker panicked");
+                }
+            }
+        }
+    }
+
+    fn held_finish() -> (Prints, mpsc::Receiver<u32>, mpsc::Sender<()>) {
+        let (arrived, arrival) = mpsc::sync_channel(1);
+        let (release, released) = mpsc::channel();
+        let (path, _) = program(
+            "finish-control",
+            r#"printf '{"ready":true,"loaded_ms":1}\n'; exec sleep 30"#,
+        );
+        let prints = Prints::journaled_gated(
+            path,
+            "model".into(),
+            QUICK,
+            to_stderr(),
+            Some(FinishGate { arrived, released }),
+        );
+        (prints, arrival, release)
+    }
+
+    #[test]
+    #[ignore = "external negative control: expected assertion failure"]
+    fn omitting_finish_cannot_claim_a_held_child_was_reaped() {
+        let (mut prints, arrival, release) = held_finish();
+        let guard = ControlWorker {
+            release: Some(release),
+            worker: prints.worker.take(),
+        };
+        // This is precisely the omitted finish: close the two channels,
+        // retain the handle only for cleanup after the expected panic.
+        drop(prints);
+        let child = arrival.recv_timeout(Duration::from_secs(5)).unwrap();
+        eprintln!("same-voice cleanup control: child {child} held before kill/wait");
+        assert!(
+            guard.worker.as_ref().unwrap().is_finished(),
+            "without finish the worker has not reached child kill/wait"
+        );
+    }
+
+    #[test]
+    #[ignore = "external positive control paired with omitted finish"]
+    fn finish_waits_for_a_held_child_to_be_reaped() {
+        let (prints, arrival, release) = held_finish();
+        let controller = thread::spawn(move || {
+            let child = arrival.recv_timeout(Duration::from_secs(5));
+            // Dropping release permits cleanup on both success and failure.
+            drop(release);
+            child
+        });
+        let finished = prints.finish();
+        let child = controller.join().unwrap().unwrap();
+        eprintln!("same-voice cleanup control: finish returned after child {child}");
+        assert_eq!(finished, Ok(()));
+    }
